    Field {
        name: "zavg",
        dtype: Float64,
    },
    Field {
        name: "ystd",
        dtype: Float64,
    },
    Field {
        name: "xbase_indices",
        dtype: List(
            Int64,
        ),
    },
]
[src/apply/mod.rs:119] struct_fields.clone() = {
    "xbase_indices": [
        List(
            shape: (1,)
            Series: '' [i64]
            [
            	2
            ],
        ),
        List(
            shape: (1,)
            Series: '' [i64]
            [
            	2
            ],
        ),
    ],
    "ystd": [
        Float64(
            0.1,
        ),
        Float64(
            0.1,
        ),
    ],
    "zavg": [
        Float64(
            1.1,
        ),
        Float64(
            1.1,
        ),
    ],
}
